CREATE TABLE tentativas_print (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT, turma TEXT, aula TEXT, horario TEXT);
CREATE TABLE provas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    titulo TEXT NOT NULL,
    descricao TEXT,
    turma TEXT,
    ativa INTEGER DEFAULT 0,
    criada_em TEXT,
    tempo_limite INTEGER DEFAULT 0
  );
