INSERT INTO prova_questoes VALUES(102,8,13,'Para abrir uma pasta, o clique correto é:','Arrastar','Clique direito','Scroll','Clique duplo','d','multipla');
INSERT INTO prova_questoes VALUES(103,8,14,'Qual extensão identifica um documento do Word?','.jpg','.mp3','.docx','.pdf','c','multipla');
INSERT INTO prova_questoes VALUES(104,8,15,'Qual é mais rápido para armazenamento permanente: HD ou SSD?','Depende da cor','SSD','São iguais','HD','b','multipla');
INSERT INTO prova_questoes VALUES(105,8,16,'O botão que ESCONDE o programa na barra de tarefas (sem fechar) é:','X (fechar)','➖ Minimizar','Alt+F4','⬜ Maximizar','b','multipla');
INSERT INTO prova_questoes VALUES(106,8,17,'Qual sistema operacional é mais usado em servidores?','iOS','Android','Linux','Windows','c','multipla');
INSERT INTO prova_questoes VALUES(107,8,18,'Como chamamos todas as partes FÍSICAS do computador?','Software','Hardware','Internet','RAM','b','multipla');
INSERT INTO prova_questoes VALUES(108,8,19,'Para reiniciar o computador, você vai em:','Fechar o monitor','Iniciar → Energia → Reiniciar','Alt + F4','Puxar o cabo e ligar novamente','b','multipla');
INSERT INTO prova_questoes VALUES(109,8,20,'O que faz o Sistema Operacional?','Conecta à internet','Armazena fotos','Gerencia o hardware e permite usar outros programas','Imprime documentos','c','multipla');
INSERT INTO prova_questoes VALUES(110,8,21,'Para COPIAR um arquivo, o atalho é:','Ctrl+V','Ctrl+Z','Ctrl+C','Ctrl+X','c','multipla');
INSERT INTO prova_questoes VALUES(111,8,22,'O que é a memória RAM?','É a placa de vídeo','É o mesmo que HD','Armazena arquivos permanentemente','Guarda dados temporariamente enquanto usa o computador','d','multipla');
INSERT INTO prova_questoes VALUES(112,8,23,'Quando devo reiniciar o computador?','Nunca','Toda hora','Quando o PC estiver lento ou após instalar programas','Só quando ligar pela primeira vez','c','multipla');
INSERT INTO prova_questoes VALUES(113,8,24,'Qual é a sequência correta do ciclo do computador?','Saída → Processamento → Entrada','Entrada → Saída → Processamento','Processamento → Entrada → Saída','Entrada → Processamento → Saída','d','multipla');
INSERT INTO prova_questoes VALUES(114,8,25,'Onde ficam os arquivos antes de serem deletados definitivamente?','Desktop','Lixeira','Downloads','Documentos','b','multipla');
INSERT INTO prova_questoes VALUES(115,8,26,'Para RENOMEAR um arquivo, a tecla usada é:','Ctrl+R','Delete','F5','F2','d','multipla');
INSERT INTO prova_questoes VALUES(116,8,27,'O atalho Ctrl+A serve para:','Selecionar tudo','Abrir um arquivo','Fechar o programa','Salvar','a','multipla');
INSERT INTO prova_questoes VALUES(117,8,28,'Para fazer Print Screen (capturar a tela):','Alt+F4','Ctrl+Print Screen','Print Screen ou PrtSc','Windows+S','c','multipla');
INSERT INTO prova_questoes VALUES(118,8,29,'O teclado é um exemplo de dispositivo de:','Armazenamento','Processamento','Entrada','Saída','c','multipla');
INSERT INTO prova_questoes VALUES(119,8,30,'Para fazer uma letra maiúscula temporária, usa-se:','Alt','Shift','Caps Lock','Ctrl','b','multipla');
INSERT INTO prova_questoes VALUES(120,8,31,'O atalho Windows + D serve para:','Abrir o Word','Desligar o computador','Deletar arquivos','Mostrar a área de trabalho','d','multipla');
INSERT INTO prova_questoes VALUES(121,8,32,'Qual a ordem correta para ligar o computador?','Tomada → Estabilizador → Monitor → Botão Power','Botão Power → Monitor → Tomada','Monitor → Botão Power → Estabilizador','Qualquer ordem funciona','a','multipla');
INSERT INTO prova_questoes VALUES(122,8,33,'Como abrir o Explorador de Arquivos rapidamente?','Alt+F4','Ctrl+E','Windows+E','Ctrl+P','c','multipla');
INSERT INTO prova_questoes VALUES(123,8,34,'O mouse é um dispositivo de:','Saída','Processamento','Entrada','Armazenamento','c','multipla');
INSERT INTO prova_questoes VALUES(124,8,35,'Qual é a diferença entre Hardware e Software?','Hardware são programas, Software são peças','São a mesma coisa','Hardware é só a CPU','Hardware são peças físicas, Software são programas','d','multipla');
CREATE TABLE prova_respostas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    prova_id INTEGER NOT NULL,
    aluno_nome TEXT NOT NULL,
    aluno_rm TEXT,
    turma TEXT,
    nota REAL,
    acertos INTEGER,
    total INTEGER,
    respondida_em TEXT,
    UNIQUE(prova_id, aluno_nome)
  );
